// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter, IVaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address asset, uint256 kink, uint256 slope0, uint256 slope1) public {
        vm.assume(asset != address(0));
        kink = bound(kink, 1, 1e27 - 1);

        AC ac = new AC();
        Proxy p = new Proxy(address(c));

        // initialize through the proxy (the implementation itself has initializers disabled)
        (bool initOk, ) = address(p).call(abi.encodeWithSelector(IVaultAdapter.initialize.selector, address(ac)));
        assertTrue(initOk, "initialize must succeed");

        bool ok;
        try IVaultAdapter(address(p)).setSlopes(asset, IVaultAdapter.SlopeData(kink, slope0, slope1)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: accessControl was stored, AC.checkAccess returns true, setSlopes succeeds.
        // Mutant: accessControl is address(0), the check decodes nothing and reverts.
        assertTrue(ok, "setSlopes must succeed for any valid slopes after initialize");
    }
}

contract AC {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}

contract Proxy {
    bytes32 private constant IMPL_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    constructor(address impl) {
        assembly {
            sstore(IMPL_SLOT, impl)
        }
    }

    fallback() external payable {
        assembly {
            let impl := sload(IMPL_SLOT)
            calldatacopy(0, 0, calldatasize())
            let success := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch success
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
}
